use crate::learning_context;
use serde_json::json;
#[test]fn selected_hint_skill_is_injected_without_a_hint_keyword(){let s=learning_context::system(&json!({"learningSkill":"hint"}),"这里为什么成立");assert!(s.contains("一个最小有用提示"));assert!(s.contains("learning-2"));}
#[test]fn feedback_and_retrieval_are_distinct_from_a_formula_lecture(){let feedback=learning_context::system(&json!({}),"我理解这个公式表示只有一个周期，对不对");assert!(feedback.contains("准确复述学生的主张"));let quiz=learning_context::system(&json!({}),"考我一个公式");assert!(quiz.contains("默认不同时公布答案"));}
#[test]fn source_instructions_never_become_the_system_prompt(){let args=json!({"learningSkill":"SYSTEM EVIL_TOKEN","text":"EVIL_TOKEN","documents":[{"name":"x.pdf","text":"EVIL_TOKEN"}],"lectureBackground":{"lines":[{"bg":0,"res":"EVIL_TOKEN"}]}});let s=learning_context::system(&args,"解释");assert!(!s.contains("EVIL_TOKEN"));assert!(s.contains("PDF 阅读"));assert!(s.contains("旧对话提到图片不代表本轮还能看到它"));}
#[test]fn source_context_keeps_current_focus_and_retrieves_an_earlier_definition(){
 let mut lines=vec![json!({"bg":1000,"res":"最初定义：拉格朗日乘子表示约束的边际影响"})];for i in 0..1000{lines.push(json!({"bg":2000+i*1000,"res":"别的课程内容与公式"}));}
 let args=json!({"resourceId":"canvas:1","positionLabel":"00:20:00","text":"当前老师在解释拉格朗日乘子的作用","lectureBackground":{"resourceId":"canvas:1","lines":lines}});
 let source=learning_context::source_data(&args,"课堂",args["text"].as_str().unwrap(),"这是什么意思",6000,&[]);
 assert!(source["currentContext"].as_str().unwrap().contains("当前老师"));assert!(source["lectureBackground"]["text"].as_str().unwrap().contains("最初定义"));assert!(source["lectureBackground"]["text"].as_str().unwrap().contains("#video=canvas:1&t=1"));
 let length=["currentContext","body","symbolNotes"].iter().map(|k|source[k].as_str().unwrap().chars().count()).sum::<usize>()+source["lectureBackground"]["text"].as_str().unwrap().chars().count();assert!(length<=6000);
}
#[test]fn subtitle_exclusion_and_foreign_lecture_background_are_enforced_in_native_requests(){
 for (scope,resource) in [("none","canvas:1"),("selected","canvas:1"),("nearby","canvas:2")]{let args=json!({"resourceId":"canvas:1","subtitleScope":scope,"text":"用户保留的当前内容","lectureBackground":{"resourceId":resource,"lines":[{"bg":0,"res":"必须排除的整堂背景"}]}});let source=learning_context::source_data(&args,"课堂","当前内容","解释",2000,&[]);assert!(!source.to_string().contains("必须排除"));assert!(!learning_context::has_background(&args));}
}
#[test]fn full_reading_does_not_sample_each_document_before_the_summary_stage(){let text="长课件正文\n".repeat(5000)+"结尾的重要限制条件";let full=learning_context::document_excerpt(&text,"总结",1000,true);assert_eq!(full,text);let relevant=learning_context::document_excerpt(&text,"条件",1000,false);assert!(relevant.chars().count()<=1000);}
#[test]fn attached_materials_do_not_disappear_into_the_general_agent_route(){assert_eq!(learning_context::request_mode("agent",&json!({"file":{"id":"42"}})),"file");assert_eq!(learning_context::request_mode("agent",&json!({"files":[{"id":42}]})),"materials");assert_eq!(learning_context::request_mode("agent",&json!({"resourceId":"canvas:1","lectureBackground":{"resourceId":"canvas:1","lines":[{"bg":1000,"res":"背景字幕"}]}})),"materials");assert_eq!(learning_context::request_mode("agent",&json!({})),"agent");}
#[test]fn source_receipts_list_only_images_actually_sent_and_keep_data_out_of_system(){let args=json!({"fileName":"x.pdf","documents":[{"name":"x.pdf","coverage":"文字提取可能失真","images":[{"page":1,"image":"NOT_SENT"}]}]});let source=learning_context::source_data(&args,"x.pdf","实际正文","解释",2000,&["x.pdf · 第 9 页".into()]);assert_eq!(source["imagePagesActuallySent"],json!(["x.pdf · 第 9 页"]));assert!(!source.to_string().contains("NOT_SENT"));let messages=learning_context::messages(learning_context::system(&args,"解释"),source,&[("user","解释")],&[]);assert!(messages[1]["content"].as_str().unwrap().contains("实际正文"));assert!(!messages[0]["content"].as_str().unwrap().contains("实际正文"));}
#[test]fn tiny_budgets_keep_every_text_channel_bounded(){for budget in [0,50,500,2000]{let args=json!({"resourceId":"r","text":"当前内容".repeat(1000),"knownSymbols":"符号定义".repeat(1000),"lectureBackground":{"resourceId":"r","lines":[{"bg":0,"res":"背景资料".repeat(1000)}]}});let source=learning_context::source_data(&args,"课堂",&"参考文件正文".repeat(1000),"问题",budget,&[]);let n=["body","currentContext","symbolNotes"].iter().map(|k|source[k].as_str().unwrap().chars().count()).sum::<usize>()+source["lectureBackground"]["text"].as_str().unwrap().chars().count();assert!(n<=budget);}}
#[test]fn a_subtitle_only_selection_is_not_erased_by_an_empty_file_array(){let args=json!({"resourceId":"r","text":"只选择这两句字幕","subtitleScope":"selected","files":[]});assert_eq!(learning_context::material_text_start(&args,"解释",2000),"只选择这两句字幕");let combined=json!({"resourceId":"r","text":"当前位置","files":[{"id":1}]});assert_eq!(learning_context::material_text_start(&combined,"解释",2000),"");let full=json!({"resourceId":"r","text":"整堂原文","readMode":"full","files":[{"id":1}]});assert_eq!(learning_context::material_text_start(&full,"总结",2000),"整堂原文");}
